// Pure gameplay physics shared by the browser game and the level simulator.
export const TILE = 44;
export const FLOOR_Y = 620;
export const CEIL_Y = 80;
export const SIZE = 46;
export const GRAVITY = 2600;
export const JUMP_V = 940;
export const PAD_V = 1260;
export const MAX_FALL = 1650;
export const DEATH_TIME = 0.75;

export function createPlayer() {
  return {
    x: 0,
    y: FLOOR_Y - SIZE,
    vy: 0,
    gravity: 1,
    onGround: true,
    rot: 0,
    alive: true,
    finished: false,
    speedMul: 1,
    buffer: 0,
    usedOrbs: new Set(),
    usedPads: new Set(),
    usedPortals: new Set(),
    progress: 0,
    airTime: 0,
    landImpact: 0,
  };
}

export function resetPlayer(p) {
  p.x = 0;
  p.y = FLOOR_Y - SIZE;
  p.vy = 0;
  p.gravity = 1;
  p.onGround = true;
  p.rot = 0;
  p.alive = true;
  p.finished = false;
  p.speedMul = 1;
  p.buffer = 0;
  p.usedOrbs.clear();
  p.usedPads.clear();
  p.usedPortals.clear();
  p.progress = 0;
  p.airTime = 0;
  p.landImpact = 0;
}

export function playerBox(p) {
  return { x: p.x, y: p.y, w: SIZE, h: SIZE };
}

export function playerHazardBox(p) {
  return { x: p.x + 8, y: p.y + 8, w: SIZE - 16, h: SIZE - 16 };
}

function overlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function spikeBox(o) {
  // A forgiving triangle approximated by a narrow box near its base.
  if (o.dir === -1) {
    return { x: o.x + 12, y: o.y + 2, w: o.size - 24, h: o.size - 10 };
  }
  return { x: o.x + 12, y: o.y - o.size + 8, w: o.size - 24, h: o.size - 10 };
}

export function hazardBox(o) {
  if (o.type === 'spike') return spikeBox(o);
  if (o.type === 'saw') {
    return { x: o.x - o.r + 7, y: o.y - o.r + 7, w: o.r * 2 - 14, h: o.r * 2 - 14 };
  }
  return { x: o.x, y: o.y, w: o.w || 0, h: o.h || 0 };
}

function die(p, events) {
  if (!p.alive) return;
  p.alive = false;
  events.push({ type: 'death', x: p.x + SIZE / 2, y: p.y + SIZE / 2 });
}

function jump(p, events, power = JUMP_V) {
  p.vy = -power * p.gravity;
  p.onGround = false;
  p.buffer = 0;
  events.push({ type: 'jump', x: p.x + SIZE / 2, y: p.y + SIZE });
}

function land(p) {
  p.vy = 0;
  p.onGround = true;
  p.rot = 0;
}

export function stepPlayer(p, level, dt, input, events) {
  if (!p.alive || p.finished) return;

  const wasGround = p.onGround;
  p.buffer = Math.max(0, p.buffer - dt);
  if (input.pressed) p.buffer = 0.13;

  // Jump orbs react to a fresh press only.
  if (input.pressed) {
    const cx = p.x + SIZE / 2;
    const cy = p.y + SIZE / 2;
    for (const o of level.objects) {
      if (o.type !== 'orb' || p.usedOrbs.has(o.id)) continue;
      const dx = cx - o.x;
      const dy = cy - o.y;
      if (dx * dx + dy * dy <= (o.r + 30) * (o.r + 30)) {
        p.usedOrbs.add(o.id);
        p.vy = -JUMP_V * 1.02 * p.gravity;
        p.onGround = false;
        p.buffer = 0;
        events.push({ type: 'orb', x: o.x, y: o.y });
        break;
      }
    }
  }

  if (wasGround && (input.held || p.buffer > 0)) {
    jump(p, events);
  }

  if (!p.onGround) {
    p.airTime += dt;
    p.vy += GRAVITY * p.gravity * dt;
    p.vy = Math.max(-MAX_FALL, Math.min(MAX_FALL, p.vy));
    p.rot += p.gravity * dt * 8.6;
  } else {
    p.airTime = 0;
    p.rot = 0;
  }

  const prevY = p.y;
  p.y += p.vy * dt;
  p.onGround = false;

  // Vertical resolution against solid blocks.
  const body = playerBox(p);
  for (const o of level.objects) {
    if (o.type !== 'block') continue;
    if (!overlap(body, o)) continue;
    const prevBottom = prevY + SIZE;
    const prevTop = prevY;
    if (p.gravity === 1 && p.vy >= 0 && prevBottom <= o.y + 16) {
      p.y = o.y - SIZE;
      p.landImpact = Math.min(1, Math.abs(p.vy) / 1200);
      land(p);
      events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y + SIZE, impact: p.landImpact });
    } else if (p.gravity === -1 && p.vy <= 0 && prevTop >= o.y + o.h - 16) {
      p.y = o.y + o.h;
      p.landImpact = Math.min(1, Math.abs(p.vy) / 1200);
      land(p);
      events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y, impact: p.landImpact });
    } else if (p.gravity === 1 && p.vy < 0) {
      // Head bonk is fatal in the runner, like GD block sides.
      die(p, events);
      return;
    } else if (p.gravity === -1 && p.vy > 0) {
      die(p, events);
      return;
    }
    body.y = p.y;
  }

  // Move forward, then resolve block sides.
  const speed = level.speed * p.speedMul;
  p.x += speed * dt;

  for (const o of level.objects) {
    if (o.type !== 'block') continue;
    const b = playerBox(p);
    if (!overlap(b, o)) continue;
    if (p.gravity === 1 && p.vy >= 0 && p.y + SIZE <= o.y + 28) {
      p.y = o.y - SIZE;
      land(p);
      events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y + SIZE, impact: 0.3 });
      continue;
    }
    if (p.gravity === -1 && p.vy <= 0 && p.y >= o.y + o.h - 28) {
      p.y = o.y + o.h;
      land(p);
      events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y, impact: 0.3 });
      continue;
    }
    die(p, events);
    return;
  }

  // Floor and ceiling.
  if (p.gravity === 1) {
    if (p.y + SIZE >= FLOOR_Y) {
      p.y = FLOOR_Y - SIZE;
      if (!p.onGround) {
        p.landImpact = Math.min(1, Math.abs(p.vy) / 1200);
        events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y + SIZE, impact: p.landImpact });
        land(p);
      }
    }
    if (p.y < CEIL_Y) {
      p.y = CEIL_Y;
      p.vy = Math.max(0, p.vy);
    }
  } else {
    if (p.y <= CEIL_Y) {
      p.y = CEIL_Y;
      if (!p.onGround) {
        p.landImpact = Math.min(1, Math.abs(p.vy) / 1200);
        events.push({ type: 'land', x: p.x + SIZE / 2, y: p.y, impact: p.landImpact });
        land(p);
      }
    }
    if (p.y + SIZE > FLOOR_Y) {
      p.y = FLOOR_Y - SIZE;
      p.vy = Math.min(0, p.vy);
    }
  }

  // Pads.
  for (const o of level.objects) {
    if (o.type !== 'pad' || p.usedPads.has(o.id)) continue;
    const hit = { x: p.x + 4, y: p.y + 4, w: SIZE - 8, h: SIZE - 8 };
    const trigger = { x: o.x - 4, y: o.y - 20, w: o.w + 8, h: 30 };
    if (overlap(hit, trigger)) {
      p.usedPads.add(o.id);
      p.vy = -PAD_V * p.gravity;
      p.onGround = false;
      events.push({ type: 'pad', x: o.x + o.w / 2, y: o.y });
    }
  }

  // Portals.
  for (const o of level.objects) {
    if (o.type !== 'portal' || p.usedPortals.has(o.id)) continue;
    if (p.x + SIZE < o.x || p.x > o.x + o.w) continue;
    if (p.y + SIZE < o.y || p.y > o.y + o.h) continue;
    p.usedPortals.add(o.id);
    if (o.kind === 'gravity') {
      p.gravity *= -1;
      p.vy = 0;
      p.onGround = false;
      events.push({ type: 'portal', kind: 'gravity', x: o.x + o.w / 2, y: p.y + SIZE / 2, dir: p.gravity });
    } else if (o.kind === 'speed') {
      p.speedMul = o.mul;
      events.push({ type: 'portal', kind: 'speed', x: o.x + o.w / 2, y: p.y + SIZE / 2, mul: o.mul });
    }
  }

  // Hazards.
  const hb = playerHazardBox(p);
  for (const o of level.objects) {
    if (o.type === 'spike' || o.type === 'saw') {
      if (Math.abs(o.x - p.x) > 180) continue;
      if (overlap(hb, hazardBox(o))) {
        die(p, events);
        return;
      }
    }
  }

  // Shards.
  const cx = p.x + SIZE / 2;
  const cy = p.y + SIZE / 2;
  for (const s of level.shards) {
    if (s.taken) continue;
    const dx = cx - s.x;
    const dy = cy - s.y;
    if (dx * dx + dy * dy < 42 * 42) {
      s.taken = true;
      events.push({ type: 'shard', id: s.id, x: s.x, y: s.y });
    }
  }

  p.progress = Math.max(0, Math.min(1, p.x / level.length));
  if (p.x + SIZE >= level.length) {
    p.finished = true;
    events.push({ type: 'finish', x: p.x + SIZE, y: p.y });
  }
}

export function levelSolids(level) {
  return level.objects.filter((o) => o.type === 'block');
}

export function findThreatAhead(p, level, lookahead) {
  let best = null;
  const laneTop = p.gravity === 1 ? FLOOR_Y - SIZE : CEIL_Y;
  const laneBottom = laneTop + SIZE;
  const probe = { x: p.x + SIZE, y: p.y + 2, w: lookahead, h: SIZE - 4 };
  for (const o of level.objects) {
    if (o.type !== 'spike' && o.type !== 'saw' && o.type !== 'block') continue;
    if (o.x + (o.w || o.size || 0) < p.x + SIZE) continue;
    if (o.x > p.x + SIZE + lookahead) continue;
    const rect = o.type === 'block' ? o : hazardBox(o);
    if (rect.y >= laneBottom + 4 || rect.y + rect.h <= laneTop - 4) continue;
    if (!overlap(probe, rect)) continue;
    if (!best || o.x < best.x) best = o;
  }
  return best;
}

import { FLOOR_Y as F, CEIL_Y as C, TILE as T } from './engine.js';

const THEMES = {
  dawn: {
    skyTop: '#170b33', skyBottom: '#5b1c6e', accent: '#ff5ec4', accent2: '#61e7ff',
    floor: '#1b0c2e', floorLine: '#ff5ec4', block: '#331a5e', blockEdge: '#9b6dff',
    spike: '#ff6ad5', grid: 'rgba(255,110,220,.14)', glow: '#ff5ec4',
  },
  rush: {
    skyTop: '#041c2c', skyBottom: '#07546b', accent: '#3dffd0', accent2: '#48a9ff',
    floor: '#041824', floorLine: '#3dffd0', block: '#0a3b4a', blockEdge: '#60ffe0',
    spike: '#56ffe0', grid: 'rgba(61,255,208,.14)', glow: '#3dffd0',
  },
  circuit: {
    skyTop: '#1f0a08', skyBottom: '#6d2410', accent: '#ffb340', accent2: '#59c8ff',
    floor: '#1a0907', floorLine: '#ffb340', block: '#4a2010', blockEdge: '#ffd27a',
    spike: '#ffb340', grid: 'rgba(255,179,64,.13)', glow: '#ffb340',
  },
  gravity: {
    skyTop: '#0b0620', skyBottom: '#232a72', accent: '#b28bff', accent2: '#42f5e4',
    floor: '#080419', floorLine: '#b28bff', block: '#231a52', blockEdge: '#cbb0ff',
    spike: '#b28bff', grid: 'rgba(178,139,255,.14)', glow: '#b28bff',
  },
  overdrive: {
    skyTop: '#21030b', skyBottom: '#7a0f1d', accent: '#ff4d4d', accent2: '#ffe45e',
    floor: '#160207', floorLine: '#ff4d4d', block: '#4d0c18', blockEdge: '#ff9b6a',
    spike: '#ff5b5b', grid: 'rgba(255,77,77,.15)', glow: '#ff4d4d',
  },
};

let objectCounter = 0;

function build(id, config, define) {
  const objects = [];
  const shards = [];
  let shardCount = 0;
  const add = (o) => objects.push({ id: `${id}-o${++objectCounter}`, ...o });
  const api = {
    spike(x, n = 1, y = F) {
      for (let i = 0; i < n; i++) add({ type: 'spike', x: x + i * T, y, size: T, dir: 1 });
      return api;
    },
    spikeDown(x, n = 1, y = C) {
      for (let i = 0; i < n; i++) add({ type: 'spike', x: x + i * T, y, size: T, dir: -1 });
      return api;
    },
    block(x, wT = 1, hT = 1, y = F - hT * T) {
      add({ type: 'block', x, y, w: wT * T, h: hT * T });
      return api;
    },
    blockAt(x, y, wT = 1, hT = 1) {
      add({ type: 'block', x, y, w: wT * T, h: hT * T });
      return api;
    },
    platform(x, y, wT = 3) {
      add({ type: 'block', x, y, w: wT * T, h: 18, platform: true });
      return api;
    },
    saw(x, y = F - 34, r = 32) {
      add({ type: 'saw', x, y, r });
      return api;
    },
    pad(x, y = F, w = 56) {
      add({ type: 'pad', x, y, w });
      return api;
    },
    orb(x, y, r = 22, kind = 'yellow') {
      add({ type: 'orb', x, y, r, kind });
      return api;
    },
    portal(x, kind, y = F - 300, h = 300, mul) {
      add({ type: 'portal', kind, x, y, h, w: 54, mul });
      return api;
    },
    shard(x, y) {
      shards.push({ id: `${id}-s${++shardCount}`, x, y, taken: false });
      return api;
    },
  };
  define(api);
  objects.sort((a, b) => a.x - b.x);
  return { id, ...config, objects, shards };
}

const LEVELS = [
  build('l1', {
    name: 'Stereo Dawn',
    tagline: 'Where the beat begins',
    difficulty: 1,
    speed: 360,
    length: 10800,
    theme: THEMES.dawn,
    bpm: 126,
    root: 57, // A3
    scale: [0, 3, 5, 7, 10],
    musicPattern: [0, 3, 7, 10, 7, 3, 5, 7, 10, 12, 10, 7, 5, 3, 0, 3],
  }, (l) => {
    l.spike(1300);
    l.spike(1900);
    l.spike(2450);
    l.spike(3000, 2);
    l.block(3600, 1, 1);
    l.spike(4200);
    l.spike(4750, 2);
    l.block(5350, 2, 1);
    l.spike(5950);
    l.spike(6500);
    l.shard(6548, 416);
    l.pad(7100);
    l.shard(7320, 330);
    l.spike(7900);
    l.spike(8450, 2);
    l.block(9000, 1, 2);
    l.spike(9550, 3);
    l.spike(10150);
    l.shard(10195, 420);
  }),

  build('l2', {
    name: 'Neon Rush',
    tagline: 'Pick up the pace',
    difficulty: 2,
    speed: 400,
    length: 12000,
    theme: THEMES.rush,
    bpm: 140,
    root: 50, // D3
    scale: [0, 2, 3, 5, 7, 8, 10],
    musicPattern: [0, 3, 7, 10, 12, 10, 7, 3, 0, 5, 8, 12, 10, 7, 5, 3],
  }, (l) => {
    l.spike(1250);
    l.spike(1750, 2);
    l.saw(2350);
    l.block(2900, 1, 1);
    l.spike(3450, 2);
    l.pad(4050);
    l.shard(4280, 330);
    l.spike(4700, 3);
    l.saw(5350);
    l.block(5900, 2, 1);
    l.spike(6500, 2);
    l.spike(7100);
    l.shard(7200, 430);
    l.saw(7700);
    l.spike(8300, 3);
    l.block(8900, 1, 2);
    l.spike(9500, 2);
    l.spike(10100, 3);
    l.block(10700, 2, 1);
    l.spike(11300);
  }),

  build('l3', {
    name: 'Circuit Breaker',
    tagline: 'Ride the current',
    difficulty: 3,
    speed: 420,
    length: 13200,
    theme: THEMES.circuit,
    bpm: 146,
    root: 52, // E3
    scale: [0, 2, 3, 5, 7, 9, 10],
    musicPattern: [0, 3, 5, 7, 10, 12, 10, 7, 5, 3, 0, 7, 10, 12, 10, 5],
  }, (l) => {
    l.spike(1250);
    l.spike(1800, 2);
    l.saw(2400);
    l.block(3000, 2, 1);
    l.spike(3650, 3);
    l.pad(4250);
    l.platform(4500, 430, 4);
    l.shard(4620, 375);
    l.spike(5000);
    l.spike(5550, 2);
    l.saw(6150);
