import { LEVELS } from '/home/runner/work/PlayGround/PlayGround/js/levels.js';
import { createPlayer, stepPlayer, findThreatAhead, hazardBox, SIZE } from '/home/runner/work/PlayGround/PlayGround/js/engine.js';
function threatStart(o){ return o.type==='block'?o.x:hazardBox(o).x; }
function decide(p,level,factor){ if(!p.onGround) return false; const speed=level.speed*p.speedMul; const threat=findThreatAhead(p,level,speed*.4); if(!threat) return false; const gap=threatStart(threat)-(p.x+SIZE); if(gap>speed*factor) return false; return true; }
for (const lid of ['l4','l5']) {
  const level=LEVELS.find(l=>l.id===lid);
  for (const s of level.shards) s.taken=false;
  const p=createPlayer(); const events=[]; let t=0;
  const near=level.shards.map(s=>({id:s.id,x:s.x,y:s.y,d:1e9,px:0,py:0}));
  while(t<90){ const pressed=decide(p,level,.12); stepPlayer(p,level,1/240,{held:false,pressed},events); if(p.finished) break; if(!p.alive) break; t+=1/240;
    const cx=p.x+SIZE/2, cy=p.y+SIZE/2;
    for(const n of near){const d=Math.hypot(cx-n.x,cy-n.y); if(d<n.d){n.d=d;n.px=cx;n.py=cy;}}
  }
  console.log(lid,'win',p.finished); for(const n of near) console.log(n.id, 'shard',Math.round(n.x),Math.round(n.y),'closest',n.d.toFixed(1),'at',Math.round(n.px),Math.round(n.py));
}
