  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.88);
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
}

#hud-attempt { color: var(--muted); font-size: 9px; white-space: nowrap; }

.progress-track {
  position: relative;
  height: 18px;
  border-radius: 999px;
  background: rgba(8, 3, 18, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.65), 0 4px 18px rgba(0, 0, 0, 0.35);
  overflow: visible;
}

.progress-fill {
  position: absolute;
  inset: 2px auto 2px 2px;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--pink), #ff9c5c 55%, var(--yellow) 78%, var(--cyan));
  box-shadow: 0 0 14px rgba(255, 94, 196, 0.75), 0 0 26px rgba(66, 245, 228, 0.35);
  transition: width 0.08s linear;
  max-width: calc(100% - 4px);
}

.progress-knob {
  position: absolute;
  top: 50%;
  left: 0%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--pink);
  box-shadow: 0 0 12px #fff, 0 0 22px var(--pink);
  transform: translate(-50%, -50%);
  transition: left 0.08s linear;
  z-index: 2;
}

.progress-pct {
  position: absolute;
  right: 9px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.9);
