+  display: flex;
+  align-items: center;
+  gap: 12px;
+  min-width: 0;
+}
+
+.editor-heading { min-width: 0; }
+
+.editor-heading .kicker { margin-bottom: 2px; }
+
+.editor-heading h2 {
+  margin: 0;
+  font-family: var(--display);
+  font-size: clamp(18px, 2.4vw, 27px);
+  font-weight: 900;
+  line-height: 1;
+  letter-spacing: 0.03em;
+  text-transform: uppercase;
+  text-shadow: 0 4px 24px rgba(0, 0, 0, 0.7);
+}
+
+.editor-head-actions {
+  display: flex;
+  align-items: center;
+  gap: 9px;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+}
+
+.editor-count {
+  padding: 7px 11px;
+  border: 1px solid rgba(255, 255, 255, 0.14);
+  border-radius: 999px;
+  background: rgba(8, 3, 19, 0.7);
+  color: var(--muted);
+  font-size: 8px;
+  font-weight: 800;
+  letter-spacing: 0.16em;
+  white-space: nowrap;
+  backdrop-filter: blur(10px);
+}
+
+.editor-save,
+.editor-test {
+  min-height: 40px;
+  padding: 8px 16px;
+  font-size: 10px;
+  border-radius: 10px;
+}
+
+.editor-test {
+  min-height: 44px;
+  padding: 8px 18px;
+  font-size: 12px;
+}
+
+.editor-test .btn-icon {
+  width: 23px;
+  height: 23px;
+  font-size: 8px;
+}
+
+.editor-dock {
+  bottom: 0;
+  display: flex;
+  flex-direction: column;
+  gap: 9px;
+  padding: 14px calc(14px + env(safe-area-inset-right)) calc(12px + env(safe-area-inset-bottom)) calc(14px + env(safe-area-inset-left));
+  background: linear-gradient(0deg, rgba(6, 2, 14, 0.94) 30%, rgba(6, 2, 14, 0.72) 72%, transparent 100%);
