+  background: linear-gradient(180deg, rgba(66, 245, 228, 0.16), rgba(66, 245, 228, 0.04));
+  box-shadow: 0 0 18px rgba(66, 245, 228, 0.16), inset 0 0 14px rgba(66, 245, 228, 0.08);
