+  font-weight: 900;
+  letter-spacing: 0.18em;
+}
+
+.editor-field input,
+.editor-field select {
+  height: 34px;
+  padding: 0 8px;
+  border: 1px solid rgba(255, 255, 255, 0.16);
+  border-radius: 8px;
